let file = """{"version":3,"file":"reportError-Dqldkhr0.js","names":[],"sources":["../../packages/shared-frontend-utils/src/telemetry.ts","../../src/platform/telemetry/redactTelemetryUrls.ts","../../src/platform/telemetry/initDatadogRum.ts","../../src/platform/telemetry/reportError.ts"],"sourcesContent":["/** The backend family a RUM session reports under, as Datadog and backend engineers name it. */\nexport type DeployEnv = 'prod-v2' | 'stg-v2' | 'test-v2'\n\n/** One RUM application for every Comfy web surface; each sets its own `service`. */\nexport const COMFY_RUM_APPLICATION = {\n  clientToken: 'pub7704486e5b64eb4ff6f62891cda45559',\n  applicationId: '041a9897-5516-4b1f-a245-1a9aa6895488',\n  site: 'us5.datadoghq.com'\n} as const\n\nexport const DEFAULT_POSTHOG_API_HOST = 'https://t.comfy.org'\n\n/** PostHog settings every Comfy web surface shares; each adds its own token, host and before_send. */\nexport const COMFY_POSTHOG_OPTIONS = {\n  ui_host: 'https://us.posthog.com',\n  autocapture: false,\n  capture_pageview: 'history_change',\n  capture_pageleave: false,\n  persistence: 'localStorage+cookie',\n  person_profiles: 'identified_only'\n} as const\n\n/**\n * Marks the console line a reporter writes for every report. RUM collects\n * `console.error` on its own, so `isRumErrorNoise` matches on this to drop the\n * untagged console copy of a failure RUM already received tagged.\n */\nexport const REPORTED_ERROR_PREFIX = '[Reported error]: '\n\nconst EXTENSION_ERROR_MESSAGES = [\n  'Invalid call to runtime.sendMessage(). Tab not found.',\n  '[messaging] In this JS context, only one listener can be setup for'\n]\n\nconst ERROR_MESSAGE_PREFIX =\n  /^(?:Unhandled promise rejection:\\s*)?(?:Error:\\s*)?$/\n\nconst RUM_NOISE_HOSTS = [\n  'facebook.com',\n  'px.ads.linkedin.com',\n  'browser-intake-us5-datadoghq.com',\n  'e2.sy-d.io',\n  'google-analytics.com',\n  'googletagmanager.com'\n]\n\nexport function isThirdPartyErrorNoise(message?: string): boolean {\n  if (!message) return false\n  return EXTENSION_ERROR_MESSAGES.some((known) => {\n    const index = message.indexOf(known)\n    return index >= 0 && ERROR_MESSAGE_PREFIX.test(message.slice(0, index))\n  })\n}\n\n/** An error no Comfy page raised or can act on. */\nexport function isRumErrorNoise(error: {\n  readonly message: string\n  readonly source?: string\n}): boolean {\n  const { message } = error\n  if (error.source === 'console' && message.startsWith(REPORTED_ERROR_PREFIX))\n    return true\n  if (isThirdPartyErrorNoise(message)) return true\n  if (message.startsWith('intervention:')) return true\n  if (message.includes('ResizeObserver loop')) return true\n\n  const isNetworkNoise =\n    message.includes('csp_violation') || message.includes('Failed to fetch')\n  return (\n    isNetworkNoise && RUM_NOISE_HOSTS.some((host) => message.includes(host))\n  )\n}\n\n/** Origin and path only: a query or fragment can carry a client secret or an email. */\nexport function stripUrlQuery(url: string): string {\n  return url.replace(/[?#].*$/s, '')\n}\n\nconst URL_PATTERN = /\\bhttps?:\\/\\/[^\\s\"'<>()]*/g\n\nconst SENSITIVE_TEXT_PATTERNS: readonly (readonly [RegExp, string])[] = [\n  [/\\beyJ[\\w-]+\\.[\\w-]+\\.[\\w-]+/g, '[token]'],\n  [/\\b(Bearer\\s+)[\\w.~+/-]+=*/gi, '$1[token]'],\n  [/\\b\\w+_secret_\\w+/g, '[token]'],\n  // Anchored on the character before the address, so a long run of\n  // address characters is scanned once instead of from every offset.\n  [\n    /(^|[^\\w.%+-])[\\w.%+-]+(?:@|%40)[\\w-]+(?:\\.[\\w-]+)*\\.[a-z]{2,}/gi,\n    '$1[email]'\n  ]\n]\n\n/** Free text with every URL query, token, client secret and email taken out. */\nexport function redactSensitiveText(text: string): string {\n  return SENSITIVE_TEXT_PATTERNS.reduce(\n    (redacted, [pattern, replacement]) =>\n      redacted.replace(pattern, replacement),\n    text.replace(URL_PATTERN, stripUrlQuery)\n  )\n}\n","/** Remove credentials, query strings, and fragments from URL-shaped text. */\nexport function redactTelemetryUrls(text: string): string {\n  if (text.length > MAX_REDACTABLE_TEXT_LENGTH) return REDACTION_SENTINEL\n  return text\n    .replace(SPACED_QUERY_URL_PATTERN, redactUrlToken)\n    .replace(URL_TOKEN_PATTERN, redactUrlToken)\n}\n\nconst MAX_REDACTABLE_TEXT_LENGTH = 16_384\nconst ABSOLUTE_URL_START = /(?:https?:)?\\/\\/[^\\s\"'<>?#]+/.source\n/**\n * The root-relative alternative starts at a non-digit, or at a digit followed\n * by a second path character. That keeps `/v?token=…` and `/a/b?token=…`\n * redacted while leaving a bare fraction such as `1/2?x` as ordinary text, so\n * non-URL messages keep their Sentry grouping.\n */\nconst ROOT_RELATIVE_URL_START =\n  /(?<!\\d)\\/(?!\\/|https?:\\/\\/)(?:[A-Za-z._~%-]|\\d(?:[A-Za-z0-9._~%/-]|(?=[?#]))|(?=[?#]))[A-Za-z0-9._~%/-]*/\n    .source\nconst RELATIVE_URL_START =\n  /(?<![A-Za-z0-9._~%/-])(?!\\d+\\/\\d+[?#])[A-Za-z0-9_~%-]+(?:[./][A-Za-z0-9._~%-]+)*/\n    .source\nconst URL_START = `(?:${ABSOLUTE_URL_START}|${ROOT_RELATIVE_URL_START}|${RELATIVE_URL_START})`\nconst SPACED_QUERY_URL_PATTERN = new RegExp(\n  `${URL_START}\\\\?[^\\\\n\"'<>]*\\\\s[^\\\\n\"'<>]*&[A-Za-z0-9_~%-]+=[^\\\\n\"'<>]*`,\n  'gi'\n)\n\nconst URL_TOKEN_PATTERN = new RegExp(\n  `(?:${ABSOLUTE_URL_START}|${ROOT_RELATIVE_URL_START})[^\\\\s\"'<>]*|${RELATIVE_URL_START}(?:\\\\?[^\\\\s\"'<>]*=[^\\\\s\"'<>]*|#[^\\\\s\"'<>]+)`,\n  'gi'\n)\n\nfunction redactUrlToken(token: string): string {\n  let redacted = ''\n  let tokenStart = 0\n  for (;;) {\n    const boundary = findGluedUrlBoundary(token, tokenStart)\n    if (!boundary) {\n      return redacted + redactSingleUrlToken(token.slice(tokenStart))\n    }\n    const { nextUrl, separator } = boundary\n    redacted += redactSingleUrlToken(token.slice(tokenStart, separator))\n    redacted += token.slice(separator, nextUrl)\n    tokenStart = nextUrl\n  }\n}\n\nfunction redactSingleUrlToken(token: string): string {\n  const { core, trailing } = peelTrailingPunctuation(token)\n  const stackSuffix = core.match(/:\\d+:\\d+$/)?.[0] ?? ''\n  const url = stackSuffix ? core.slice(0, -stackSuffix.length) : core\n  const clean = url.split(/[?#]/, 1)[0]\n  const absolute = clean.match(/^((?:https?:)?\\/\\/)([^/]*)(.*)$/i)\n  if (!absolute) return `${clean}${stackSuffix}${trailing}`\n\n  const [, prefix, authority, path] = absolute\n  const userInfoEnd = authority.lastIndexOf('@')\n  return `${prefix}${authority.slice(userInfoEnd + 1)}${path}${stackSuffix}${trailing}`\n}\n\nfunction findGluedUrlBoundary(\n  token: string,\n  tokenStart: number\n): { separator: number; nextUrl: number } | undefined {\n  const urlStartPattern = /(?:https?:)?\\/\\//g\n  urlStartPattern.lastIndex = tokenStart + 1\n  for (const match of token.matchAll(urlStartPattern)) {\n    const nextUrl = match.index\n    let separator = nextUrl\n    while (separator > 0 && /[[\\](){};,]/.test(token[separator - 1])) {\n      separator--\n    }\n    if (separator < nextUrl || token[nextUrl - 1] === '/') {\n      return {\n        separator: token[nextUrl - 1] === '/' ? nextUrl - 1 : separator,\n        nextUrl\n      }\n    }\n  }\n}\n\nfunction peelTrailingPunctuation(token: string): {\n  core: string\n  trailing: string\n} {\n  let trailing = ''\n  const separatorSuffix = token.match(/[,;]+$/)?.[0] ?? ''\n  if (separatorSuffix) {\n    trailing = separatorSuffix\n    token = token.slice(0, -separatorSuffix.length)\n  }\n  const bracketSuffix = token.match(/[)\\]]+$/)?.[0] ?? ''\n  if (bracketSuffix) {\n    const peelCount = countExcessClosingBrackets(token, bracketSuffix)\n    if (peelCount) {\n      trailing = token.slice(-peelCount) + trailing\n      token = token.slice(0, -peelCount)\n    }\n  }\n  return { core: token, trailing }\n}\n\nfunction countExcessClosingBrackets(token: string, suffix: string): number {\n  const counts = {\n    parens: countCharacter(token, ')') - countCharacter(token, '('),\n    brackets: countCharacter(token, ']') - countCharacter(token, '[')\n  }\n  let count = 0\n  for (let index = suffix.length - 1; index >= 0; index--) {\n    if (!consumeExcessClosingBracket(suffix[index], counts)) break\n    count++\n  }\n  return count\n}\n\nfunction countCharacter(text: string, target: string): number {\n  let count = 0\n  for (const character of text) {\n    if (character === target) count++\n  }\n  return count\n}\n\nfunction consumeExcessClosingBracket(\n  bracket: string,\n  counts: { parens: number; brackets: number }\n): boolean {\n  if (bracket === ')' && counts.parens > 0) {\n    counts.parens--\n    return true\n  }\n  if (bracket === ']' && counts.brackets > 0) {\n    counts.brackets--\n    return true\n  }\n  return false\n}\n\nexport const REDACTION_SENTINEL = '[Redacted]'\nconst MAX_REDACTION_DEPTH = 32\nconst MAX_REDACTION_NODES = 1_000\n\n/**\n * Copy a telemetry payload with URL metadata removed from every reachable\n * string.\n *\n * Only plain records, arrays, `Error`s, `URL`s and primitives survive the copy.\n * Every other object — `Date`, `Map`, `Request`, class instances — becomes\n * `[Redacted]`, because inspecting it safely is not possible for an arbitrary\n * accessor. Accessor properties are dropped rather than invoked for the same\n * reason. Traversal is bounded by depth and node count, and anything past\n * either bound also becomes `[Redacted]`.\n */\nexport function redactTelemetryValues(\n  values: Record<string, unknown> | undefined\n): Record<string, unknown> | undefined {\n  if (!values) return values\n  return redactPlainObject(\n    values,\n    {\n      ancestors: new WeakSet<object>(),\n      memo: new WeakMap<object, unknown>(),\n      nodesRemaining: MAX_REDACTION_NODES\n    },\n    0\n  )\n}\n\nexport function redactTelemetryError(error: unknown): Error {\n  let source: Error\n  if (error instanceof Error) {\n    source = error\n  } else {\n    try {\n      source = new Error(String(error))\n    } catch {\n      source = new Error('[Redacted]')\n    }\n  }\n  return redactError(\n    source,\n    {\n      ancestors: new WeakSet<object>(),\n      memo: new WeakMap<object, unknown>(),\n      nodesRemaining: MAX_REDACTION_NODES\n    },\n    0\n  )\n}\n\ninterface RedactionContext {\n  ancestors: WeakSet<object>\n  memo: WeakMap<object, unknown>\n  nodesRemaining: number\n}\n\nfunction redactValue(\n  value: unknown,\n  context: RedactionContext,\n  depth = 0\n): unknown {\n  if (typeof value === 'string') return redactTelemetryUrls(value)\n  if (typeof value === 'function') return REDACTION_SENTINEL\n  if (typeof value !== 'object' || value === null) return value\n  const guarded = guardedRedactionValue(value, context, depth)\n  if (guarded) return guarded.value\n  return redactClassifiedValue(classifyObject(value), value, context, depth)\n}\n\nfunction redactClassifiedValue(\n  classification: ObjectClassification,\n  value: object,\n  context: RedactionContext,\n  depth: number\n): unknown {\n  switch (classification.kind) {\n    case 'error':\n      return redactError(classification.value, context, depth)\n    case 'array':\n      return redactArray(classification.value, context, depth)\n    case 'url':\n      return redactTelemetryUrls(classification.value.href)\n    case 'plain':\n      return redactPlainObject(value, context, depth)\n    case 'other':\n    case 'unsafe':\n      return REDACTION_SENTINEL\n  }\n}\n\nfunction guardedRedactionValue(\n  value: object,\n  context: RedactionContext,\n  depth: number\n): { value: unknown } | undefined {\n  if (context.ancestors.has(value)) return { value: '[Circular]' }\n  if (context.memo.has(value)) return { value: context.memo.get(value) }\n  if (depth >= MAX_REDACTION_DEPTH || context.nodesRemaining-- <= 0) {\n    return { value: REDACTION_SENTINEL }\n  }\n}\n\nfunction redactArray(\n  value: unknown[],\n  context: RedactionContext,\n  depth: number\n): unknown[] {\n  const output: unknown[] = []\n  output.length = value.length\n  context.memo.set(value, output)\n  context.ancestors.add(value)\n  try {\n    const entries = ownDataEntries(value)\n    if (!entries) return [REDACTION_SENTINEL]\n    for (const [key, nested] of entries) {\n      if (!isArrayIndex(key, value.length)) continue\n      output[Number(key)] = redactValue(nested, context, depth + 1)\n    }\n    return output\n  } finally {\n    context.ancestors.delete(value)\n  }\n}\n\nfunction isArrayIndex(key: string, length: number): boolean {\n  const index = Number(key)\n  return (\n    Number.isInteger(index) &&\n    index >= 0 &&\n    index < length &&\n    `${index}` === key\n  )\n}\n\nfunction redactPlainObject(\n  value: object,\n  context: RedactionContext,\n  depth: number\n): Record<string, unknown> {\n  const entries = ownDataEntries(value)\n  if (!entries) return { redaction: REDACTION_SENTINEL }\n  const output: Record<string, unknown> = Object.create(null)\n  context.memo.set(value, output)\n  context.ancestors.add(value)\n  try {\n    for (const [key, nested] of entries) {\n      Object.defineProperty(output, redactTelemetryUrls(key), {\n        configurable: true,\n        enumerable: true,\n        value: redactValue(nested, context, depth + 1),\n        writable: true\n      })\n    }\n    return output\n  } finally {\n    context.ancestors.delete(value)\n  }\n}\n\ntype ObjectClassification =\n  | { kind: 'error'; value: Error }\n  | { kind: 'array'; value: unknown[] }\n  | { kind: 'url'; value: URL }\n  | { kind: 'plain' | 'other' | 'unsafe' }\n\nfunction classifyObject(value: object): ObjectClassification {\n  try {\n    if (value instanceof Error) return { kind: 'error', value }\n    if (value instanceof URL) return { kind: 'url', value }\n    if (Array.isArray(value)) return { kind: 'array', value }\n    const prototype = Object.getPrototypeOf(value)\n    return prototype === Object.prototype || prototype === null\n      ? { kind: 'plain' }\n      : { kind: 'other' }\n  } catch {\n    return { kind: 'unsafe' }\n  }\n}\n\nfunction ownDataEntries(value: object): [string, unknown][] | null {\n  try {\n    return Object.entries(Object.getOwnPropertyDescriptors(value))\n      .filter(\n        ([, descriptor]) => descriptor.enumerable && 'value' in descriptor\n      )\n      .map(([key, descriptor]) => [key, descriptor.value])\n  } catch {\n    return null\n  }\n}\n\nfunction redactError(\n  source: Error,\n  context: RedactionContext,\n  depth: number\n): Error {\n  const properties = ownDataProperties(source)\n  if (!properties) return new Error(REDACTION_SENTINEL)\n  const message = readErrorString(source, properties, 'message')\n  const redactedMessage =\n    message === undefined ? '' : redactTelemetryUrls(message)\n  const output = new Error(redactedMessage)\n  context.memo.set(source, output)\n  context.ancestors.add(source)\n  try {\n    if ('cause' in properties) {\n      output.cause = redactValue(properties.cause, context, depth + 1)\n    }\n    const name = readErrorString(source, properties, 'name')\n    if (name !== undefined) {\n      output.name = redactTelemetryUrls(name)\n    }\n    const stack = readErrorString(source, properties, 'stack')\n    if (stack !== undefined) {\n      output.stack = redactTelemetryUrls(stack)\n    }\n    return output\n  } finally {\n    context.ancestors.delete(source)\n  }\n}\n\nfunction readErrorString(\n  source: Error,\n  properties: Record<string, unknown>,\n  key: 'message' | 'name' | 'stack'\n): string | undefined {\n  if (typeof properties[key] === 'string') return properties[key]\n  try {\n    const ownDescriptor = Object.getOwnPropertyDescriptor(source, key)\n    if (ownDescriptor && !('value' in ownDescriptor)) return REDACTION_SENTINEL\n    let prototype = Object.getPrototypeOf(source)\n    while (prototype) {\n      const descriptor = Object.getOwnPropertyDescriptor(prototype, key)\n      if (descriptor) {\n        return 'value' in descriptor && typeof descriptor.value === 'string'\n          ? descriptor.value\n          : REDACTION_SENTINEL\n      }\n      prototype = Object.getPrototypeOf(prototype)\n    }\n    return undefined\n  } catch {\n    return undefined\n  }\n}\n\nfunction ownDataProperties(value: object): Record<string, unknown> | null {\n  try {\n    return Object.fromEntries(\n      Object.entries(Object.getOwnPropertyDescriptors(value))\n        .filter(([, descriptor]) => 'value' in descriptor)\n        .map(([key, descriptor]) => [key, descriptor.value])\n    )\n  } catch {\n    return null\n  }\n}\n","// oxlint-disable-next-line no-restricted-imports -- the telemetry layer owns the sinks that reportError() fans out to\nimport { datadogRum } from '@datadog/browser-rum'\n\nimport { COMFY_RUM_APPLICATION } from '@comfyorg/shared-frontend-utils/telemetry'\nimport type { DeployEnv } from '@comfyorg/shared-frontend-utils/telemetry'\n\nimport { rumBeforeSend } from './datadogRumBeforeSend'\nimport { trackUserManualRefresh } from './manualRefreshTracker'\n\nconst DATADOG_ENV_BY_HOSTNAME = new Map<string, DeployEnv>([\n  ['cloud.comfy.org', 'prod-v2'],\n  ['stagingcloud.comfy.org', 'stg-v2'],\n  ['testcloud.comfy.org', 'test-v2']\n])\nconst FRONTEND_CONTEXT_FETCH_TIMEOUT_MS = 1_000\ntype FrontendBucket = 'canary' | 'stable'\nconst FRONTEND_BUCKETS: readonly FrontendBucket[] = ['canary', 'stable']\nlet initializationPromise: Promise<void> | undefined\nlet resolvedBucket: FrontendBucket | undefined\n\n/**\n * The canary/stable split, resolved once from the deploy's own\n * `X-Frontend-Bucket` response header rather than inferred from a release or\n * version string (D25) — other telemetry sinks that want the same fact\n * should read this instead of re-fetching it. `undefined` means the split\n * isn't known yet (probe still pending, failed, or off a tracked version),\n * not 'stable' — collapsing that into a default would mistag reports and\n * corrupt the canary/stable RUM comparison this header exists to support.\n */\nexport function getFrontendBucket(): FrontendBucket | undefined {\n  return resolvedBucket\n}\n\nfunction parseFrontendBucket(value: string | null): FrontendBucket {\n  return FRONTEND_BUCKETS.includes(value as FrontendBucket)\n    ? (value as FrontendBucket)\n    : 'stable'\n}\n\nasync function setFrontendContext(): Promise<void> {\n  const response = await fetch(window.location.origin, {\n    method: 'HEAD',\n    cache: 'no-store',\n    signal: AbortSignal.timeout(FRONTEND_CONTEXT_FETCH_TIMEOUT_MS)\n  })\n  if (!response.ok) return\n\n  const frontendVersion = response.headers.get('X-Frontend-Version')\n  if (frontendVersion !== __COMFYUI_FRONTEND_COMMIT__) return\n\n  resolvedBucket = parseFrontendBucket(\n    response.headers.get('X-Frontend-Bucket')\n  )\n  datadogRum.setGlobalContextProperty('bucket', resolvedBucket)\n  datadogRum.setGlobalContextProperty('version', frontendVersion)\n}\n\nasync function initializeDatadogRum(env: string): Promise<void> {\n  datadogRum.setGlobalContextProperty(\n    'comfyui_frontend_version',\n    __COMFYUI_FRONTEND_VERSION__\n  )\n  await setFrontendContext().catch(() => {})\n  if (datadogRum.getInitConfiguration()) return\n\n  datadogRum.init({\n    ...COMFY_RUM_APPLICATION,\n    service: 'comfy-cloud-frontend',\n    env,\n    version: __COMFYUI_FRONTEND_COMMIT__,\n    beforeSend: rumBeforeSend,\n    sessionSampleRate: 100,\n    sessionReplaySampleRate: 0,\n    trackFeatureFlagsForEvents: ['action', 'vital', 'long_task', 'resource'],\n    allowedTracingUrls: [/^https:\\/\\/[^/]+\\.comfy\\.org/]\n  })\n  trackUserManualRefresh()\n}\n\n/**\n * Maps a hostname to the deploy environment name Datadog/backend engineers\n * already use to distinguish prod from testcloud/staging — shared here so a\n * caller identifying \"which backend is this\" (e.g. a bug-report payload)\n * reads the same classification RUM does, instead of a second hostname list\n * that can drift from this one.\n */\nexport function resolveDeployEnv(\n  hostname = window.location.hostname\n): DeployEnv | undefined {\n  return (\n    DATADOG_ENV_BY_HOSTNAME.get(hostname) ??\n    (hostname.endsWith('.testenvs.comfy.org') ? 'test-v2' : undefined)\n  )\n}\n\nexport function initDatadogRum(\n  hostname = window.location.hostname\n): Promise<void> {\n  const env = resolveDeployEnv(hostname)\n  if (!env || datadogRum.getInitConfiguration()) return Promise.resolve()\n\n  initializationPromise ??= initializeDatadogRum(env).finally(() => {\n    initializationPromise = undefined\n  })\n  return initializationPromise\n}\n","// oxlint-disable-next-line no-restricted-imports -- the telemetry layer owns the sinks that reportError() fans out to\nimport { datadogRum } from '@datadog/browser-rum'\n// oxlint-disable-next-line no-restricted-imports -- the telemetry layer owns the sinks that reportError() fans out to\nimport { captureException, isEnabled as isSentryEnabled } from '@sentry/vue'\n\nimport type { ComfyDesktop2TelemetryProperties } from '@comfyorg/comfyui-desktop-bridge-types'\nimport { REPORTED_ERROR_PREFIX } from '@comfyorg/shared-frontend-utils/telemetry'\n\nimport { isCloud } from '@/platform/distribution/types'\nimport { getFrontendBucket } from '@/platform/telemetry/initDatadogRum'\nimport { isHostTelemetryEnabled } from '@/platform/telemetry/hostTelemetryEnabled'\nimport { toError } from '@/utils/errorUtil'\n\nimport { redactTelemetryValues } from './redactTelemetryUrls'\n\nexport type Surface =\n  | 'agent'\n  | 'billing'\n  | 'graph'\n  | 'auth'\n  | 'assets'\n  | 'workspace'\n  | 'platform'\n\nexport interface ReportErrorOptions {\n  /**\n   * Stable machine-readable slug for this failure mode. Lands as the\n   * native RUM `error.type`, the `error_type` Sentry tag, and the legacy\n   * `error_type` RUM context field.\n   */\n  errorType: string\n  /** Product surface responsible for acting on this failure. */\n  surface: Surface\n  tags?: Record<string, string | number | boolean | undefined>\n  context?: Record<string, unknown>\n  level?: 'warning' | 'error'\n  /**\n   * Opt out of the console line for callers that already wrote one — only\n   * `assert()`, which logs before any reporter is registered.\n   */\n  logToConsole?: boolean\n}\n\ninterface DeliveryState {\n  sentry: boolean\n  datadog: boolean\n  desktop: boolean\n}\n\ninterface PendingReport {\n  error: Error\n  options: ReportErrorOptions\n  delivered: DeliveryState\n}\n\nconst NO_DELIVERY: DeliveryState = {\n  sentry: false,\n  datadog: false,\n  desktop: false\n}\n\n/**\n * Reports raised before any sink is live are held here rather than dropped.\n * On cloud, Datadog RUM arrives behind `initTelemetry()`'s dynamic imports, so\n * its delivery remains pending even when Sentry received the report first.\n */\nconst pendingReports: PendingReport[] = []\nconst MAX_PENDING_REPORTS = 25\nconst reportedErrors = new WeakSet<Error>()\n\n/**\n * Prevents an error with its own complete diagnostic from being reported again\n * by a higher-level catch boundary. The original error remains unchanged for\n * user-facing handling.\n */\nexport function markErrorReported(error: Error): void {\n  reportedErrors.add(error)\n}\n\nconst isDatadogRumLive = () => datadogRum.getInitConfiguration() !== undefined\n\nconst definedEntriesOf = <V>(\n  values: Record<string, V> | undefined\n): Record<string, Exclude<V, undefined>> =>\n  Object.fromEntries(\n    Object.entries(values ?? {}).filter(\n      (entry): entry is [string, Exclude<V, undefined>] =>\n        entry[1] !== undefined\n    )\n  )\n\n/** Written from `options`, so a caller tag of the same name never lands. */\nconst RESERVED_TAG_KEYS = new Set(['error_type', 'level', 'surface', 'bucket'])\n\nlet dispatching = false\n\nconst definedTagsOf = (\n  tags: ReportErrorOptions['tags']\n): Record<string, string | number | boolean> =>\n  Object.fromEntries(\n    Object.entries(tags ?? {}).filter(\n      (entry): entry is [string, string | number | boolean] => {\n        const [key, value] = entry\n        return (\n          !RESERVED_TAG_KEYS.has(key) &&\n          (typeof value === 'string' ||\n        